        key = (row["deployment"], row["row_id"])
        if key in seen:
            raise ValueError("Duplicate issuance identity.")
        seen.add(key)
        dep = row["deployment"]
        if dep not in sources:
            raise ValueError("Unknown issuance deployment.")
        for k in ("site", "archive", "configuration"):
            if row.get(k) != sources[dep][k]:
