                    )
                if gap["reason"] == "PING_QUARANTINE" and gap.get("quarantined_pings") != [165]:
                    raise ValueError("Missing ping-boundary quarantine explanation.")
                if gap["reason"] == "CONFIGURATION_BOUNDARY" and (
